<script setup lang="ts">
import { Activity, Database, Globe2, KeyRound, ShieldCheck } from 'lucide-vue-next'
const api=useApi(); const runtime=useRuntimeConfig()
const { data: settings, refresh }=await useAsyncData('admin-settings',()=>api.request<any[]>('/admin/settings').catch(()=>[]))
const config=reactive({ taxRate: 0.0825, supportEmail: 'support@vomtek.com' })
watch(settings,(v)=>{ if(v){ const tax=v.find((x:any)=>x.key==='taxRate'); const mail=v.find((x:any)=>x.key==='supportEmail'); if(tax?.value?.rate!=null) config.taxRate=tax.value.rate; if(mail?.value?.email) config.supportEmail=mail.value.email } },{immediate:true})
async function save(key:string,value:any){await api.request(`/admin/settings/${key}`,{method:'POST',body:{value}});await refresh()}
const checks=[{l:'API',v:'Connected',i:Activity,ok:true},{l:'Diagnostic engine',v:'Fallback-ready',i:Database,ok:true},{l:'Object storage',v:'Demo local',i:Globe2,ok:false},{l:'Auth',v:'JWT · 7 day',i:KeyRound,ok:true},{l:'Tenant isolation',v:'Enforced',i:ShieldCheck,ok:true}]
</script>
<template><div><div class="mb-5"><p class="label-mono text-signal-deep">Administration</p><h1 class="mt-1 font-display text-[32px] tracking-[-.04em]">Settings.</h1><p class="mt-1 text-[11.5px] text-ink/45">Environment, integrations and operational controls.</p></div><div class="grid gap-4 lg:grid-cols-12"><div class="space-y-3 lg:col-span-7"><div v-for="c in checks" :key="c.l" class="a-card flex items-center gap-3 p-4"><component :is="c.i" :size="16" class="text-ink/35"/><p class="flex-1 text-[12px]">{{ c.l }}</p><span class="font-mono text-[8px] uppercase tracking-[.06em]" :class="c.ok?'text-mint-deep':'text-signal-deep'">{{ c.v }}</span></div></div><div class="a-card p-5 lg:col-span-5"><p class="font-display text-[19px]">Runtime configuration</p><div class="mt-4 space-y-3 font-mono text-[10px] text-ink/50"><div><p class="text-ink/30">API base</p><p class="break-all">{{ runtime.public.apiBase }}</p></div><div><p class="text-ink/30">Website</p><p>{{ runtime.public.siteUrl }}</p></div><div><p class="text-ink/30">Environment</p><p>demo</p></div></div><div class="mt-5 space-y-3 border-t border-ink/10 pt-4"><div><label class="a-label">Tax rate</label><div class="flex gap-2"><input v-model.number="config.taxRate" type="number" step="0.0001" class="a-input"><button class="btn btn-dark !text-[9px]" @click="save('taxRate',{rate:config.taxRate})">Save</button></div></div><div><label class="a-label">Support email</label><div class="flex gap-2"><input v-model="config.supportEmail" class="a-input"><button class="btn btn-dark !text-[9px]" @click="save('supportEmail',{email:config.supportEmail})">Save</button></div></div></div></div></div></div></template>
